## Interview Context
This question evaluates serverless workflow design, AWS Step Functions expertise, and production-ready error handling patterns in distributed systems.

## Key Components
- **State Machine Design**: Task states for order validation, payment processing, inventory updates, and notification delivery with parallel branches for concurrent operations
- **Retry Patterns**: Exponential backoff with jitter (max 3 retries), custom retry policies for transient failures, and circuit breaker patterns for downstream services
- **Error Handling**: Catch blocks for specific error types (PaymentFailed, InsufficientInventory), dead letter queue integration, and custom error metrics with CloudWatch
- **State Management**: DynamoDB for order state persistence, distributed tracing with X-Ray, and idempotency keys for safe retries
- **Implementation**: Lambda functions with proper IAM roles, payload validation schemas, and timeout configurations aligned with Step Function limits

## Code Example
```json
{
  "Comment": "Serverless order processing workflow",
  "StartAt": "ValidateOrder",
  "States": {
    "ValidateOrder": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:us-east-1:123456789012:function:validate-order",
      "Retry": [{
        "ErrorEquals": ["Lambda.Timeout", "Lambda.Unknown"],
        "IntervalSeconds": 2,
        "MaxAttempts": 3,
        "BackoffRate": 2.0
      }],
      "Catch": [{
        "ErrorEquals": ["InvalidOrder"],
        "Next": "HandleValidationError",
        "ResultPath": "$.error"
      }],
      "Next": "ProcessPayment"
    },
    "ProcessPayment": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:us-east-1:123456789012:function:process-payment",
      "Retry": [{
        "ErrorEquals": ["PaymentGatewayTimeout"],
        "IntervalSeconds": 5,
        "MaxAttempts": 2,
        "BackoffRate": 1.5
      }],
      "Catch": [{
        "ErrorEquals": ["PaymentFailed"],
        "Next": "HandlePaymentError",
        "ResultPath": "$.paymentError"
      }],
      "Next": "UpdateInventory"
    },
    "UpdateInventory": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:us-east-1:123456789012:function:update-inventory",
      "TimeoutSeconds": 30,
      "HeartbeatSeconds": 10,
      "Retry": [{
        "ErrorEquals": ["DynamoDB.ProvisionedThroughputExceeded"],
        "IntervalSeconds": 10,
        "MaxAttempts": 3
      }],
      "Next": "SendNotification"
    },
    "SendNotification": {
      "Type": "Parallel",
      "Branches": [
        {
          "StartAt": "EmailCustomer",
          "States": {
            "EmailCustomer": {
              "Type": "Task",
              "Resource": "arn:aws:lambda:us-east-1:123456789012:function:send-email",
              "End": true
            }
          }
        },
        {
          "StartAt": "UpdateAnalytics",
          "States": {
            "UpdateAnalytics": {
              "Type": "Task",
              "Resource": "arn:aws:lambda:us-east-1:123456789012:function:update-analytics",
              "End": true
            }
          }
        }
      ],
      "Next": "OrderComplete"
    },
    "HandleValidationError": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:us-east-1:123456789012:function:log-validation-error",
      "Next": "OrderFailed"
    },
    "HandlePaymentError": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:us-east-1:123456789012:function:handle-payment-error",
      "Next": "OrderFailed"
    },
    "OrderComplete": {
      "Type": "Succeed"
    },
    "OrderFailed": {
      "Type": "Fail",
      "Cause": "Order processing failed",
      "Error": "OrderProcessingError"
    }
  }
